<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRouter} from 'vue-router'
import {ArrowUpRight,ArrowRight,Sparkles,Flame,Leaf,Wallet,Send,Plus,Heart,Check,Scale,Utensils,ChevronRight,ShieldCheck} from 'lucide-vue-next'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,post,put,state,localDate,dateText,logout,type Dish} from '../api'
import DishCard from '../components/DishCard.vue'
import Chart from '../components/Chart.vue'
const props=defineProps<{page:string}>(),router=useRouter()
const loading=ref(false),busy=ref(false),menu=ref<Dish[]>([]),allDishes=ref<Dish[]>([]),favorites=ref<string[]>([]),records=ref<any[]>([]),notifications=ref<any[]>([]),rec=ref<any>(null),profile=ref<any>({}),energy=ref<any>({}),meal=ref('午餐'),canteen=ref(''),category=ref('全部'),search=ref(''),message=ref(''),chat=ref<any[]>([])
const allergenText=ref(''),dislikeText=ref(''),preferenceText=ref(''),password=ref({old_password:'',new_password:''}),recordOpen=ref(false),recordDate=ref(localDate()),recordItems=ref<any[]>([]),feedbackOpen=ref(false),feedback=ref({rating:5,content:''})
const visibleDishes=computed(()=>{const source=props.page==='/favorites'?allDishes.value.filter(d=>favorites.value.includes(d.id)&&d.is_demo===(state.mode==='demo')):menu.value;return source.filter(d=>(category.value==='全部'||d.category===category.value)&&d.name.includes(search.value))})
const todayRecords=computed(()=>records.value.filter(r=>r.date===localDate()))
const total=computed(()=>todayRecords.value.reduce((a,r)=>({kcal:a.kcal+r.nutrients.kcal,protein:a.protein+r.nutrients.protein}),{kcal:0,protein:0}))
const weeklyChart=computed(()=>{const groups:Record<string,number>={};records.value.forEach(r=>groups[r.date]=(groups[r.date]||0)+r.nutrients.kcal);const dates=Object.keys(groups).sort().slice(-7);return {color:['#2c775a'],tooltip:{trigger:'axis'},grid:{left:45,right:15,top:25,bottom:25},xAxis:{type:'category',data:dates.map(d=>d.slice(5)),axisLine:{show:false},axisTick:{show:false}},yAxis:{type:'value',name:'kcal',splitLine:{lineStyle:{color:'#edf0ea'}}},series:[{type:'bar',data:dates.map(d=>groups[d]),barWidth:24,itemStyle:{borderRadius:[5,5,0,0]}}]}})
async function load(){loading.value=true;try{const result=await Promise.all([api('/dishes'),api('/me/favorites'),api('/me/meal-records?mode='+state.mode),api('/me/profile'),api('/me/notifications')]);allDishes.value=result[0];favorites.value=result[1];records.value=result[2];profile.value=result[3].profile;energy.value=result[3].energy;notifications.value=result[4];allergenText.value=profile.value.allergens.join('、');dislikeText.value=profile.value.dislikes.join('、');preferenceText.value=profile.value.preferences.join('、');if(['/','/menu','/recommend','/assistant'].includes(props.page)){menu.value=await api(`/menus?meal=${meal.value}&mode=${state.mode}${canteen.value?'&canteen_id='+canteen.value:''}`);await generate(false)}}catch{}finally{loading.value=false}}
async function generate(refresh=true){busy.value=true;try{rec.value=await post('/recommendations',{meal:meal.value,mode:state.mode,canteen_id:canteen.value||null,refresh})}catch{}finally{busy.value=false}}
watch(()=>[props.page,state.mode,meal.value,canteen.value],load,{immediate:true})
async function favorite(id:string){try{const r=await post('/me/favorites/'+id);favorites.value=r.favorite?[...favorites.value,id]:favorites.value.filter(x=>x!==id)}catch{}}
const split=(s:string)=>s.split(/[,，、\n]/).map(v=>v.trim()).filter(Boolean)
async function saveProfile(){busy.value=true;try{const r=await put('/me/profile',{...profile.value,allergens:split(allergenText.value),dislikes:split(dislikeText.value),preferences:split(preferenceText.value)});energy.value=r.energy;ElMessage.success('饮食档案已更新')}catch{}finally{busy.value=false}}
function openRecord(dish?:Dish){recordItems.value=dish?[{dish_id:dish.id,servings:1,leftover_fraction:0}]:rec.value?.combination?.dishes.map((d:Dish)=>({dish_id:d.id,servings:1,leftover_fraction:0}))||[{dish_id:'',servings:1,leftover_fraction:0}];recordDate.value=localDate();recordOpen.value=true}
async function saveRecord(){busy.value=true;try{await post('/me/meal-records',{date:recordDate.value,meal:meal.value,items:recordItems.value});recordOpen.value=false;records.value=await api('/me/meal-records?mode='+state.mode);ElMessage.success('用餐记录已保存，营养值为自报估算')}catch{}finally{busy.value=false}}
async function deleteRecord(id:string){try{await ElMessageBox.confirm('删除这条自报用餐记录？','删除记录',{type:'warning'});await api('/me/meal-records/'+id,{method:'DELETE'});await load()}catch{}}
async function readNotice(id:string){try{await post('/me/notifications/'+id+'/read');notifications.value=await api('/me/notifications')}catch{}}
async function send(){if(!message.value.trim())return;const q=message.value;message.value='';chat.value.push({role:'user',text:q});busy.value=true;try{const result=await post('/assistant',{message:q,meal:meal.value,mode:state.mode,canteen_id:canteen.value||null});rec.value=result;chat.value.push({role:'assistant',text:result.reason+'\n'+result.reminder,source:result.source,trace:result.trace})}catch{}finally{busy.value=false}}
async function saveFeedback(){try{const cid=rec.value?.combination?.dishes[0]?.canteen_id||state.canteens[0]?.id;if(!cid){ElMessage.warning('暂无食堂');return};await post('/feedback',{...feedback.value,canteen_id:cid,recommendation_id:rec.value?.id});feedbackOpen.value=false;feedback.value.content='';ElMessage.success('谢谢你的反馈')}catch{}}
async function changePassword(){try{await post('/auth/password',password.value);await logout();router.push('/login');ElMessage.success('密码已修改，请重新登录')}catch{}}
</script>
<template><div v-loading="loading">
<template v-if="page==='/'">
 <section class="hero"><div class="hero-copy"><span class="pill"><span class="status-dot"></span> 为更健康的校园生活</span><h2>好好吃饭，<br>也好好珍惜。</h2><p>让每一份食物，遇见恰到好处的你。<br>今天的专属营养搭配，已经为你准备好了。</p><el-button type="primary" size="large" @click="router.push('/recommend')">发现今日搭配 <ArrowUpRight :size="17"/></el-button><span class="hero-footnote"><ShieldCheck :size="14"/> 基于你的偏好 · 按需取餐</span></div><img class="hero-image" src="/assets/hero.svg" alt="米饭、鸡肉和蔬菜组成的均衡餐盘"><div class="hero-sticker"><Leaf :size="17"/><div><b>一餐一小步</b><small>健康与节约同行</small></div></div></section>
 <div class="metrics"><div class="metric"><span class="metric-icon"><Flame/></span><div><label>今日摄入估算</label><strong>{{total.kcal.toFixed(0)}} <small>kcal</small></strong><span>来自主动记录的 {{todayRecords.length}} 餐</span></div></div><div class="metric"><span class="metric-icon blue"><Utensils/></span><div><label>今日蛋白质估算</label><strong>{{total.protein.toFixed(1)}} <small>g</small></strong><span>配方估算，仅供参考</span></div></div><div class="metric"><span class="metric-icon amber"><Wallet/></span><div><label>每餐预算</label><strong>¥{{profile.budget||20}}</strong><span>推荐优先考虑你的预算</span></div></div><div class="metric"><span class="metric-icon pink"><Heart/></span><div><label>发现喜欢的菜品</label><strong>{{favorites.length}} <small>道</small></strong><span>收藏让下次选餐更轻松</span></div></div></div>
</template>
<template v-if="['/','/menu','/recommend','/favorites'].includes(page)">
 <div class="section-heading"><div><h2>{{page==='/favorites'?'把喜欢的味道留下':page==='/menu'?'今日食堂 · 新鲜上桌':'为你搭配，刚刚好'}} <span v-if="page!=='/favorites'" class="tiny-badge">{{rec?.source||'规则推荐'}}</span></h2><p class="muted">{{page==='/favorites'?'收藏的菜品仍以当日供应情况为准。':'营养由配方计算，推荐结合偏好与预算。'}}</p></div><router-link v-if="page==='/'" to="/menu" class="text-link">全部菜单 <ArrowRight :size="16"/></router-link></div>
 <div class="toolbar"><el-select v-model="canteen" placeholder="全部食堂" clearable style="width:160px"><el-option v-for="c in state.canteens" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-segmented v-model="meal" :options="['早餐','午餐','晚餐']"/><el-input v-model="search" placeholder="搜索喜欢的菜品" clearable style="width:200px"/><el-button v-if="page!=='/favorites'" @click="generate(true)" :loading="busy"><Sparkles :size="16"/> 换一组搭配</el-button></div>
 <section v-if="rec?.combination&&page!=='/favorites'&&page!=='/menu'" class="recommendation-panel"><div class="recommend-top"><div><span class="eyebrow">YOUR BALANCED PLATE</span><h3>一份均衡，一份满足</h3><p>{{rec.reason}}</p></div><div class="recommend-price"><b>¥{{rec.combination.price.toFixed(1)}}</b><span>整餐参考价格</span></div></div><div class="dish-grid"><DishCard v-for="d in rec.combination.dishes" :key="d.id" :dish="d" :favorite="favorites.includes(d.id)" @favorite="favorite" @record="openRecord"/></div><div class="recommend-footer"><div class="nutrition-tags"><span>{{rec.combination.nutrients.kcal}} kcal</span><span>蛋白质 {{rec.combination.nutrients.protein}}g</span><span>碳水 {{rec.combination.nutrients.carbs}}g</span><span>脂肪 {{rec.combination.nutrients.fat}}g</span></div><div><el-button @click="feedbackOpen=true">反馈搭配</el-button><el-button type="primary" @click="openRecord()">记录这一餐 <Plus :size="15"/></el-button></div></div><div class="gentle-reminder"><Leaf :size="16"/>{{rec.reminder}}</div></section>
 <el-empty v-else-if="!visibleDishes.length" :description="state.mode==='real'?'暂无真实菜品，请由食堂管理员发布菜单':'暂无符合条件的菜品'"/>
 <template v-if="['/menu','/favorites'].includes(page)"><div class="category-tabs"><button v-for="c in ['全部','主食','蛋白类','蔬菜','水果']" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="dish-grid"><DishCard v-for="d in visibleDishes" :key="d.id" :dish="d" :favorite="favorites.includes(d.id)" @favorite="favorite" @record="openRecord"/></div></template>
 <el-alert v-if="rec&&!rec.combination&&page!=='/favorites'" :title="rec.reason" type="info" :closable="false"/>
 <div v-if="page==='/'" class="two-col bottom-cards"><section class="panel"><div class="section-heading"><h3>我的饮食节奏</h3><router-link to="/records" class="text-link">查看记录 <ChevronRight :size="15"/></router-link></div><Chart v-if="records.length" :option="weeklyChart"/><el-empty v-else description="记录第一餐，让饮食趋势慢慢清晰" :image-size="70"/></section><section class="campus-card"><span class="eyebrow">SMALL ACTION, BIG CHANGE</span><Leaf :size="36"/><h2>光盘不勉强，<br>适量最重要。</h2><p>选择小份，吃完再添。<br>你的每一个小习惯，都让校园更绿色。</p><router-link to="/profile" class="text-link">完善我的饮食偏好 <ArrowUpRight :size="16"/></router-link></section></div>
 <el-collapse v-if="page==='/recommend'&&rec"><el-collapse-item title="推荐依据与工具执行摘要"><p>{{rec.energy?.basis}}</p><p>成年人维持能量估算：{{rec.energy?.daily_kcal?rec.energy.daily_kcal+' kcal/日':'资料不足或不适用'}}；BMI：{{rec.energy?.bmi??'不适用'}}</p><p v-for="step in rec.trace" :key="step">{{step}}</p></el-collapse-item></el-collapse>
</template>
<template v-else-if="page==='/profile'"><div class="two-col profile-layout"><section class="panel"><h2>了解你，才能更适合你</h2><p class="muted">身体资料自愿填写。缺少资料时，仍可获得一般菜品搭配。</p><el-form label-position="top" @submit.prevent="saveProfile"><div class="form-grid"><el-form-item label="身高 / cm"><el-input-number v-model="profile.height_cm" :min="100" :max="230" controls-position="right"/></el-form-item><el-form-item label="体重 / kg"><el-input-number v-model="profile.weight_kg" :min="25" :max="300" controls-position="right"/></el-form-item><el-form-item label="年龄"><el-input-number v-model="profile.age" :min="10" :max="100" controls-position="right"/></el-form-item><el-form-item label="能量公式使用的生理性别"><el-select v-model="profile.sex" clearable placeholder="可不填写"><el-option label="男性" value="male"/><el-option label="女性" value="female"/></el-select></el-form-item><el-form-item label="活动水平"><el-select v-model="profile.activity"><el-option v-for="(label,value) in {sedentary:'以久坐为主',light:'轻度活动',moderate:'中度活动',active:'较高活动量'}" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="饮食目标"><el-select v-model="profile.goal"><el-option label="均衡饮食" value="balanced"/><el-option label="保持体重" value="maintain"/><el-option label="运动与体能" value="fitness"/></el-select></el-form-item><el-form-item label="每餐预算 / 元"><el-input-number v-model="profile.budget" :min="1" :max="200"/></el-form-item></div><el-form-item label="过敏原（用顿号分隔，例如：鸡蛋、大豆、牛奶）"><el-input v-model="allergenText" placeholder="无过敏原可留空"/></el-form-item><el-form-item label="忌口 / 不喜欢的食材"><el-input v-model="dislikeText" placeholder="例如：香菜、辣椒"/></el-form-item><el-form-item label="偏好的菜品或食材"><el-input v-model="preferenceText" placeholder="例如：西兰花、鸡肉"/></el-form-item><el-form-item><el-checkbox v-model="profile.special_condition">未成年以外的特殊情况：孕哺期或需疾病饮食管理</el-checkbox></el-form-item><div class="consent-box"><el-checkbox v-model="profile.llm_consent">同意将身体资料、饮食偏好与最近饮食摘要发送至配置的外部大模型</el-checkbox><p class="small muted">不发送账号身份。不勾选时仅在本地规则计算，仍可使用推荐功能。</p></div><el-button type="primary" native-type="submit" :loading="busy">保存饮食档案 <Check :size="16"/></el-button></el-form></section><aside><section class="panel profile-summary"><Scale :size="30"/><h3>你的身体资料概览</h3><div class="summary-number">{{energy.bmi??'—'}}<small>BMI（成年人）</small></div><div class="summary-number">{{energy.daily_kcal??'—'}}<small>kcal / 日 · 维持能量估算</small></div><p class="muted small">{{energy.note}}</p><p class="muted small">{{energy.basis}}</p><el-alert title="不能仅凭身高体重判断营养状况，特殊饮食需求请咨询专业人员。" type="info" :closable="false"/></section></aside></div></template>
<template v-else-if="page==='/assistant'"><section class="assistant-layout"><div class="panel chat-panel"><div class="assistant-header"><span class="brand-mark"><Sparkles/></span><div><h3>膳衡营养助手</h3><span class="muted small">{{profile.llm_consent?'根据配置调用大模型，失败时自动使用规则':'本地规则模式 · 未授权外部模型'}}</span></div></div><div class="chat-messages"><div class="chat-bubble assistant"><b>今天想怎么吃？</b><p>我可以结合你的饮食档案、今日菜单和用餐记录，帮你筛选搭配。菜品、价格与营养值均以系统菜单为准。</p></div><div v-for="(c,i) in chat" :key="i" class="chat-bubble" :class="c.role"><span v-if="c.source" class="tiny-badge">{{c.source}}</span><p>{{c.text}}</p><details v-if="c.trace"><summary>工具执行摘要</summary><p v-for="s in c.trace" :key="s" class="small">{{s}}</p></details></div><div v-if="busy" class="muted small">正在读取菜单并生成搭配…</div></div><div class="suggested-questions"><button v-for="q in ['今天有什么均衡搭配？','帮我选预算内的午餐','如何减少食物剩余？']" :key="q" @click="message=q;send()">{{q}}</button></div><form class="chat-input" @submit.prevent="send"><el-input v-model="message" placeholder="说说你的饮食需求…" :maxlength="1000"/><el-button type="primary" native-type="submit" :loading="busy" aria-label="发送"><Send :size="18"/></el-button></form></div><aside class="panel"><h3>当前推荐</h3><template v-if="rec?.combination"><div v-for="d in rec.combination.dishes" :key="d.id" class="mini-dish"><img :src="d.image_url||'/assets/vegetables.svg'" :alt="d.name"><div><b>{{d.name}}</b><small>{{d.kcal}} kcal · ¥{{d.price}}</small></div></div><p class="muted small">{{rec.reason}}</p><el-button type="primary" class="full" @click="openRecord()">记录这一餐</el-button></template><el-empty v-else description="暂无符合条件的搭配" :image-size="70"/></aside></section></template>
<template v-else-if="page==='/records'"><div class="section-heading"><div><h2>认真吃饭，也认真记录</h2><p class="muted">个人记录由你主动填写，营养数据为自报估算。</p></div><el-button type="primary" @click="openRecord()"><Plus :size="16"/>记录一餐</el-button></div><div class="panel"><Chart v-if="records.length" :option="weeklyChart"/><el-table :data="records" empty-text="还没有记录，开始记录第一餐吧"><el-table-column prop="date" label="日期"/><el-table-column prop="meal" label="餐次" width="80"/><el-table-column label="菜品"><template #default="{row}">{{row.items.map((i:any)=>i.dish_name).join('、')}}</template></el-table-column><el-table-column label="摄入能量估算"><template #default="{row}">{{row.nutrients.kcal}} kcal</template></el-table-column><el-table-column label="蛋白质估算"><template #default="{row}">{{row.nutrients.protein}} g</template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button link type="danger" @click="deleteRecord(row.id)">删除</el-button></template></el-table-column></el-table></div></template>
<template v-else-if="page==='/messages'"><section class="panel"><div class="section-heading"><h2>与你有关的新消息</h2><span class="tiny-badge">{{notifications.filter(n=>!n.read).length}} 条未读</span></div><el-empty v-if="!notifications.length" description="暂时没有新消息"/><article v-for="n in notifications" :key="n.id" class="notification" :class="{unread:!n.read}"><span class="notice-icon"><Heart :size="20"/></span><div><h3>{{n.title}}</h3><p>{{n.content}}</p><small class="muted">{{dateText(n.created_at)}}</small></div><el-button v-if="!n.read" link type="primary" @click="readNotice(n.id)">标记已读</el-button></article></section></template>
<template v-else-if="page==='/settings'"><section class="panel narrow"><h2>账号与安全</h2><p class="muted">当前账号：{{state.user?.username}}。修改密码后，所有登录会话将失效。</p><el-form label-position="top" @submit.prevent="changePassword"><el-form-item label="原密码"><el-input v-model="password.old_password" type="password" show-password/></el-form-item><el-form-item label="新密码（至少8位）"><el-input v-model="password.new_password" type="password" show-password/></el-form-item><el-button type="primary" native-type="submit">更新密码</el-button></el-form></section></template>
<el-empty v-else description="页面不存在，请从左侧导航进入"/>
<el-dialog v-model="recordOpen" title="记录这一餐" width="min(680px,94vw)"><p class="muted small">摄入量按份数 × (1 − 剩余比例) 估算；不是摄像头称重结果。</p><div class="toolbar"><el-date-picker v-model="recordDate" type="date" value-format="YYYY-MM-DD"/><el-select v-model="meal" style="width:120px"><el-option v-for="m in ['早餐','午餐','晚餐']" :key="m" :value="m"/></el-select></div><div v-for="(item,i) in recordItems" :key="i" class="meal-editor"><el-select v-model="item.dish_id" filterable placeholder="选择菜品"><el-option v-for="d in allDishes.filter(d=>d.is_demo===(state.mode==='demo'))" :key="d.id" :label="d.name+' · '+d.canteen_name" :value="d.id"/></el-select><div><label class="small muted">供餐份数</label><el-input-number v-model="item.servings" :min="0.1" :max="10" :step="0.5"/></div><div><label class="small muted">剩余比例</label><el-select v-model="item.leftover_fraction"><el-option v-for="(label,key) in {'0':'吃完了','0.25':'剩余1/4','0.5':'剩余一半','0.75':'剩余3/4','1':'未食用'}" :key="key" :label="label" :value="Number(key)"/></el-select></div><el-button link type="danger" @click="recordItems.splice(i,1)">移除</el-button></div><el-button text type="primary" @click="recordItems.push({dish_id:'',servings:1,leftover_fraction:0})">+ 添加菜品</el-button><template #footer><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRecord">保存记录</el-button></template></el-dialog>
<el-dialog v-model="feedbackOpen" title="告诉我们搭配是否合适" width="min(460px,94vw)"><el-rate v-model="feedback.rating"/><el-input v-model="feedback.content" type="textarea" :rows="4" placeholder="份量、口味或推荐建议…" maxlength="1000"/><template #footer><el-button type="primary" @click="saveFeedback">提交反馈</el-button></template></el-dialog>
</div></template>
